package com.campusiq.auth.security;
import com.campusiq.user.repository.UserRepository; import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.authority.AuthorityUtils; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserRepository users; public JwtAuthenticationFilter(JwtService j,UserRepository u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,java.io.IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{String email=jwt.email(h.substring(7));users.findByEmail(email).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.getId(),null,AuthorityUtils.NO_AUTHORITIES)));}catch(JwtException ignored){} chain.doFilter(req,res);} }
